using System;
using System.Collections.Generic;
using UnityEngine;

namespace Game.Units.Mech.Art
{
    /// <summary>
    /// Part name -> mech_frame@v1 segment id mapping for a mech prefab, plus its named sockets.
    /// Generated by Game.Units.Mech.Art.Editor.MechFrameImport; never edited by hand.
    /// Paths are relative to the prefab root (Transform.Find syntax).
    /// </summary>
    [CreateAssetMenu(menuName = "Game/Mech/Part Map", fileName = "MechPartMap")]
    public sealed class MechPartMap : ScriptableObject
    {
        [Serializable]
        public struct Part
        {
            public string segmentId;     // as spelled in mech_frame@v1, e.g. "forearm_L"
            public string partName;      // e.g. "MechBalanced_forearm_L"
            public string parentSegmentId;
            public string path;          // relative to the prefab root
        }

        [Serializable]
        public struct Socket
        {
            public string socketName;    // e.g. "MechBalanced_socket_hardpoint_L"
            public string kind;          // shoulder | hip | elbow | hardpoint
            public string side;          // L | R
            public string parentSegmentId;
            public string path;
        }

        public string schema = MechFrameConfig.SchemaV1;
        public string frameId;
        public TextAsset frameConfig;
        public List<Part> parts = new List<Part>();
        public List<Socket> sockets = new List<Socket>();

        public Transform ResolvePart(Transform root, string segmentId)
        {
            foreach (var p in parts)
                if (p.segmentId == segmentId) return root.Find(p.path);
            return null;
        }

        public Transform ResolveSocket(Transform root, string kind, string side)
        {
            foreach (var s in sockets)
                if (s.kind == kind && s.side == side) return root.Find(s.path);
            return null;
        }

        /// <summary>
        /// Points one segment at a different transform (limb swap through mapping data). Paths of the
        /// parts and sockets below the old transform are re-rooted under the new one.
        /// </summary>
        public void Remap(string segmentId, string newPath, string newPartName)
        {
            int idx = parts.FindIndex(p => p.segmentId == segmentId);
            if (idx < 0) throw new KeyNotFoundException(segmentId);
            var oldPrefix = parts[idx].path + "/";
            var newPrefix = newPath + "/";
            for (int i = 0; i < parts.Count; i++)
            {
                var p = parts[i];
                if (i == idx) { p.path = newPath; p.partName = newPartName; }
                else if (p.path.StartsWith(oldPrefix, StringComparison.Ordinal)) p.path = newPrefix + p.path.Substring(oldPrefix.Length);
                parts[i] = p;
            }
            for (int i = 0; i < sockets.Count; i++)
            {
                var s = sockets[i];
                if (s.path.StartsWith(oldPrefix, StringComparison.Ordinal)) s.path = newPrefix + s.path.Substring(oldPrefix.Length);
                sockets[i] = s;
            }
        }

        public static string PathOf(Transform root, Transform t)
        {
            var names = new List<string>();
            for (var c = t; c != null && c != root; c = c.parent) names.Add(c.name);
            names.Reverse();
            return string.Join("/", names);
        }
    }
}
